-- Browser supplies identifiers only. This RPC atomically resolves canonical truth, creates Phase-G evidence and queues one command.
drop function if exists public.persist_phase_n_certification_preflight(jsonb,jsonb);
alter table public.phase_n_operations_commands add column if not exists request_hash text, add column if not exists certification_run_id uuid references public.customer_system_certification_runs(id), add column if not exists max_attempts integer not null default 5;
create unique index if not exists phase_n_one_certification_command on public.phase_n_operations_commands(certification_run_id) where certification_run_id is not null;

create or replace function public.request_phase_n_certification(p_customer_id uuid,p_account_id uuid,p_execution_plan_id text,p_decision_id text,p_idempotency_key text,p_requested_by uuid)
returns table(command_id uuid,certification_run_id uuid,duplicate boolean) language plpgsql security definer set search_path=public,extensions as $$
declare a connected_execution_accounts;d execution_account_policy_decisions;artifact certified_runtime_artifacts;plan jsonb;conn provider_connections;binding execution_entitlement_bindings;owner_ok boolean;configured uuid;run_id uuid;cmd phase_n_operations_commands;hash text;provider text;env text;entry_qty numeric;expiry timestamptz;existing phase_n_operations_commands;
begin if auth.role()<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED';end if;if nullif(p_idempotency_key,'') is null then raise exception 'IDEMPOTENCY_KEY_REQUIRED';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_customer_id::text||':'||p_account_id::text||':'||p_idempotency_key,0));
 hash:=encode(extensions.digest(convert_to(jsonb_build_object('customer',p_customer_id,'account',p_account_id,'plan',p_execution_plan_id,'decision',p_decision_id)::text,'UTF8'),'sha256'),'hex');
 select * into existing from phase_n_operations_commands where customer_id=p_customer_id and execution_account_id=p_account_id and idempotency_key=p_idempotency_key;
 if found then if existing.request_hash is distinct from hash then raise exception 'IDEMPOTENCY_CONTENT_CONFLICT';end if;return query select existing.id,existing.certification_run_id,true;return;end if;
 select customer_id into configured from phase_n_customer_configuration where key='CUSTOMER_001' and disabled_at is null;if configured is distinct from p_customer_id then raise exception 'CUSTOMER_001_NOT_EXPLICITLY_CONFIGURED';end if;
 select * into a from connected_execution_accounts where id=p_account_id and customer_id=p_customer_id for update;if not found then raise exception 'ACCOUNT_OWNERSHIP_REQUIRED';end if;
 select * into d from execution_account_policy_decisions where id=p_decision_id and execution_account_id=a.id and customer_id=a.customer_id;if not found or d.decision not in('ALLOW','REDUCE') or d.approved_quantity is null then raise exception 'PHASE_D_DECISION_NOT_EXECUTABLE';end if;
 select * into artifact from certified_runtime_artifacts where execution_plan->>'execution_plan_id'=p_execution_plan_id and account_id in(a.id::text,a.account_id) order by created_at desc limit 1;plan:=artifact.execution_plan;if plan is null then raise exception 'PERSISTED_EXECUTION_PLAN_REQUIRED';end if;
 provider:=plan->>'provider';env:=upper(coalesce(plan#>>'{routing,environment}',a.environment));expiry:=(plan->>'planned_at')::timestamptz+interval '10 minutes';
 if plan->>'schema_version'<>'execution-plan/v1' or plan->>'status'<>'PLANNED' or plan#>>'{routing,account_id}' not in(a.id::text,a.account_id) then raise exception 'EXECUTION_PLAN_ROUTE_INVALID';end if;
 if plan#>>'{risk_decision,decision_id}'<>p_decision_id or plan#>>'{risk_decision,authorized_envelope,policy_version}'<>d.policy_version then raise exception 'EXECUTION_PLAN_DECISION_LINEAGE_MISMATCH';end if;
 if provider<>case when lower(a.provider)='mt5' and upper(a.account_mode) like 'PROP%' then 'MT5_PROP' when lower(a.provider)='mt5' then 'MT5_PERSONAL' else upper(a.provider) end then raise exception 'EXECUTION_PLAN_PROVIDER_MISMATCH';end if;
 if not ((provider='BINANCE' and env='TESTNET') or (provider in('BYBIT','MT5_PERSONAL','MT5_PROP') and env='DEMO')) then raise exception 'SANDBOX_ENVIRONMENT_REQUIRED';end if;
 select coalesce(sum((o->>'quantity')::numeric),0) into entry_qty from jsonb_array_elements(plan->'orders') o where o->>'role' in('ENTRY','ENTRY_TP1','ENTRY_TP2');if entry_qty<>d.approved_quantity then raise exception 'PHASE_D_QUANTITY_LINEAGE_MISMATCH';end if;
 if coalesce((plan#>>'{risk_decision,authorized_envelope,authorized_risk_percent}')::numeric,d.authorized_risk_pct)<>d.authorized_risk_pct or expiry<=clock_timestamp() then raise exception 'RISK_OR_EXPIRY_REVALIDATION_FAILED';end if;
 if not exists(select 1 from jsonb_array_elements(plan->'orders') o where o->>'role'='STOP_LOSS' or (o->>'stop_loss')::numeric>0) then raise exception 'PROTECTION_PARAMETERS_REQUIRED';end if;
 select * into conn from provider_connections where execution_account_id=a.id and customer_id=a.customer_id;if conn.state not in('CONNECTED','VERIFIED') or conn.last_heartbeat_at<clock_timestamp()-interval '3 minutes' or (provider like 'MT5%' and conn.bridge_identity is null) or (provider in('BINANCE','BYBIT') and (not coalesce((conn.capabilities->>'trading')::boolean,false) or coalesce((conn.capabilities->>'withdrawal')::boolean,true))) then raise exception 'CURRENT_PROVIDER_CAPABILITY_REQUIRED';end if;
 select * into binding from execution_entitlement_bindings where execution_account_id=a.id and customer_id=a.customer_id and state='ACTIVE';select exists(select 1 from phase_n_owner_test_authorizations x where x.execution_account_id=a.id and x.customer_id=a.customer_id and x.revoked_at is null and x.expires_at>clock_timestamp()) into owner_ok;if binding.id is null and not owner_ok then raise exception 'ENTITLEMENT_OR_OWNER_TEST_AUTHORIZATION_REQUIRED';end if;
 if a.runtime_control<>'START' or not a.monitor_enabled or exists(select 1 from crypto_account_execution_truth t where t.execution_account_id=a.id and t.lifecycle_state='SUBMISSION_UNCERTAIN') or exists(select 1 from mt5_account_execution_truth t where t.execution_account_id=a.id and t.lifecycle_state='SUBMISSION_UNCERTAIN') then raise exception 'ACCOUNT_LOCK_OR_RECONCILIATION_REQUIRED';end if;
 insert into customer_system_certification_runs(certification_reference,customer_id,execution_account_id,account_type,provider,environment,status,decision_id,signal_id,execution_intent_id,execution_plan_id,provider_client_order_id,strategy_id,strategy_version,symbol,side,requested_quantity,submitted_quantity,authorized_risk_pct,credential_capabilities,provider_health,protection_state,expires_at)
 values('CUSTOMER_001',a.customer_id,a.id,case when provider='MT5_PROP' then 'PROP' else 'PERSONAL' end,provider,env,'PRECHECK_PASSED',d.id,d.signal_id,d.intent_id,p_execution_plan_id,coalesce(plan#>>'{orders,0,client_order_id}',p_execution_plan_id),plan#>>'{strategy_plan,identity,strategy_id}',plan#>>'{strategy_plan,identity,strategy_version}',plan#>>'{routing,canonical_symbol}',plan#>>'{orders,0,side}',d.approved_quantity,d.approved_quantity,d.authorized_risk_pct,conn.capabilities,'HEALTHY','REQUIRED',expiry) returning id into run_id;
 insert into customer_system_certification_checks(run_id,customer_id,execution_account_id,check_code,passed,safe_evidence) select run_id,a.customer_id,a.id,code,true,evidence from (values('SERVER_PLAN_LOADED',jsonb_build_object('execution_plan_id',p_execution_plan_id)),('PHASE_D_LINEAGE_CURRENT',jsonb_build_object('decision_id',d.id)),('OWNERSHIP_PROVIDER_ENVIRONMENT_CURRENT',jsonb_build_object('provider',provider,'environment',env)),('CAPABILITY_HEALTH_CURRENT',jsonb_build_object('health',conn.state)),('PROTECTION_AND_LOCKS_CURRENT','{}'::jsonb))v(code,evidence);
 insert into phase_n_operations_commands(customer_id,execution_account_id,action,idempotency_key,status,safe_payload,requested_by,request_hash,certification_run_id)
 values(a.customer_id,a.id,'START_CERTIFICATION',p_idempotency_key,'QUEUED',jsonb_build_object('certificationRunId',run_id,'executionPlanId',p_execution_plan_id,'decisionId',p_decision_id),p_requested_by,hash,run_id) returning * into cmd;
 return query select cmd.id,run_id,false;end$$;
revoke all on function public.request_phase_n_certification(uuid,uuid,text,text,text,uuid) from public,anon,authenticated;grant execute on function public.request_phase_n_certification(uuid,uuid,text,text,text,uuid) to service_role;

-- Dispatch-time loader repeats mutable gates and returns the persisted production-shaped plan only to service role.
create or replace function public.load_phase_n_certification_dispatch(p_command_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare c phase_n_operations_commands;r customer_system_certification_runs;a connected_execution_accounts;d execution_account_policy_decisions;conn provider_connections;plan jsonb;entry_qty numeric;authorized boolean;begin if auth.role()<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED';end if;select * into c from phase_n_operations_commands where id=p_command_id and action='START_CERTIFICATION' and status='CLAIMED' for update;select * into r from customer_system_certification_runs where id=c.certification_run_id and status='PRECHECK_PASSED' for update;select * into a from connected_execution_accounts where id=c.execution_account_id and customer_id=c.customer_id;select * into d from execution_account_policy_decisions where id=r.decision_id and execution_account_id=a.id and customer_id=a.customer_id;select * into conn from provider_connections where execution_account_id=a.id and customer_id=a.customer_id;select execution_plan into plan from certified_runtime_artifacts where execution_plan->>'execution_plan_id'=r.execution_plan_id and account_id in(a.id::text,a.account_id) order by created_at desc limit 1;select coalesce(sum((o->>'quantity')::numeric),0) into entry_qty from jsonb_array_elements(plan->'orders')o where o->>'role' in('ENTRY','ENTRY_TP1','ENTRY_TP2');select exists(select 1 from execution_entitlement_bindings b where b.execution_account_id=a.id and b.customer_id=a.customer_id and b.state='ACTIVE') or exists(select 1 from phase_n_owner_test_authorizations x where x.execution_account_id=a.id and x.customer_id=a.customer_id and x.revoked_at is null and x.expires_at>clock_timestamp()) into authorized;if c.id is null or r.id is null or plan is null or d.id is null then raise exception 'CANONICAL_CERTIFICATION_DISPATCH_UNAVAILABLE';end if;if r.expires_at<=clock_timestamp() or plan->>'schema_version'<>'execution-plan/v1' or plan->>'status'<>'PLANNED' or plan#>>'{risk_decision,decision_id}'<>d.id or plan#>>'{risk_decision,authorized_envelope,policy_version}'<>d.policy_version or entry_qty<>d.approved_quantity or coalesce((plan#>>'{risk_decision,authorized_envelope,authorized_risk_percent}')::numeric,-1)<>d.authorized_risk_pct or a.runtime_control<>'START' or not a.monitor_enabled or not authorized or conn.state not in('CONNECTED','VERIFIED') or conn.last_heartbeat_at<clock_timestamp()-interval '3 minutes' or (r.provider like 'MT5%' and conn.bridge_identity is null) or (r.provider in('BINANCE','BYBIT') and (not coalesce((conn.capabilities->>'trading')::boolean,false) or coalesce((conn.capabilities->>'withdrawal')::boolean,true))) or exists(select 1 from customer_system_certification_checks x where x.run_id=r.id and not x.passed) or exists(select 1 from crypto_account_execution_truth t where t.execution_account_id=a.id and t.lifecycle_state='SUBMISSION_UNCERTAIN') or exists(select 1 from mt5_account_execution_truth t where t.execution_account_id=a.id and t.lifecycle_state='SUBMISSION_UNCERTAIN') then raise exception 'DISPATCH_REVALIDATION_BLOCKED';end if;return jsonb_build_object('run_id',r.id,'plan',plan,'provider',r.provider,'decision_id',r.decision_id);end$$;
revoke all on function public.load_phase_n_certification_dispatch(uuid) from public,anon,authenticated;grant execute on function public.load_phase_n_certification_dispatch(uuid) to service_role;

-- Expired leases are terminal once bounded attempts are exhausted; uncertain submissions remain reconciliation-only in the consumer.
create or replace function public.claim_phase_n_operations_command(p_worker_id text,p_lease_seconds integer default 30) returns setof public.phase_n_operations_commands language plpgsql security definer set search_path=public as $$declare picked uuid;begin if auth.role()<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED';end if;update phase_n_operations_commands set status='FAILED',safe_error='MAX_ATTEMPTS_EXHAUSTED',completed_at=clock_timestamp(),claimed_at=null,lease_expires_at=null,lease_token=null,worker_id=null where status='CLAIMED' and lease_expires_at<clock_timestamp() and attempt>=max_attempts;update phase_n_operations_commands set status='QUEUED',claimed_at=null,lease_expires_at=null,lease_token=null,worker_id=null where status='CLAIMED' and lease_expires_at<clock_timestamp() and attempt<max_attempts;select id into picked from phase_n_operations_commands where status='QUEUED' and available_at<=clock_timestamp() and attempt<max_attempts order by created_at for update skip locked limit 1;if picked is null then return;end if;return query update phase_n_operations_commands set status='CLAIMED',attempt=attempt+1,claimed_at=clock_timestamp(),lease_expires_at=clock_timestamp()+make_interval(secs=>least(greatest(p_lease_seconds,5),300)),lease_token=gen_random_uuid(),worker_id=p_worker_id,updated_at=clock_timestamp() where id=picked returning *;end$$;

create or replace function public.finish_phase_n_operations_command(p_id uuid,p_lease_token uuid,p_success boolean,p_result jsonb,p_safe_error text default null,p_retryable boolean default false) returns boolean language plpgsql security definer set search_path=public as $$declare changed integer;begin if auth.role()<>'service_role' then raise exception 'SERVICE_ROLE_REQUIRED';end if;update phase_n_operations_commands set status=case when p_success then 'COMPLETED' when p_retryable and attempt<max_attempts then 'QUEUED' else 'FAILED' end,result_projection=case when p_success then coalesce(p_result,'{}') else '{}' end,safe_error=case when p_success then null when p_retryable and attempt>=max_attempts then 'MAX_ATTEMPTS_EXHAUSTED:'||left(p_safe_error,160) else left(p_safe_error,200) end,available_at=case when p_retryable and attempt<max_attempts then clock_timestamp()+make_interval(secs=>least(300,attempt*15)) else available_at end,completed_at=case when p_success or not p_retryable or attempt>=max_attempts then clock_timestamp() else null end,claimed_at=null,lease_expires_at=null,lease_token=null,worker_id=null,updated_at=clock_timestamp() where id=p_id and status='CLAIMED' and lease_token=p_lease_token and lease_expires_at>=clock_timestamp();get diagnostics changed=row_count;return changed=1;end$$;
